banned = input()
message = input()
words = message.split()
out = []
for w in words:
    if w == banned:
        out.append("*" * len(banned))
    else:
        out.append(w)
print(" ".join(out))

line = input()
words = line.split()
freq = {}
for w in words:
    if w in freq:
        freq[w] += 1
    else:
        freq[w] = 1
items = sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))
for word, cnt in items:
    print(word, cnt)

code = input()
i = 0
while i < len(code):
    ch = code[i]
    if ch.isdigit():
        kind = "DIGIT"
    else:
        kind = "ALPHA"
    start = i
    while i < len(code):
        if kind == "DIGIT" and code[i].isdigit():
            i += 1
        elif kind == "ALPHA" and code[i].isalpha():
            i += 1
        else:
            break
    run = code[start:i]
    print(kind, run, len(run))
